SELECT po.id AS id, po.po_code AS poCode, v.name AS vendorName, po.status AS status FROM purchase_orders as po INNER JOIN vendors as v ON po.vendor_id = v.id WHERE po.status > 0 AND po.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId}) AND po.location_id IN (SELECT location_id FROM user_locations WHERE user_id = #{filter.userId})
AND po.po_code LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY
${filter.orderBy}
po.id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

