mapper.select:
SELECT SUM(total_cost) AS totalCost FROM ( SELECT total_cost AS total_cost FROM purchase_orders INNER JOIN purchase_order_services ON purchase_orders.id = purchase_order_services.purchase_order_id
UNION ALL
SELECT total_price * -1 AS total_cost FROM purchase_returns INNER JOIN purchase_return_services ON purchase_returns.id = purchase_return_services.purchase_return_id
) AS CombinedData;

SELECT SUM(total_cost) AS totalCost FROM ( SELECT total_cost AS total_cost FROM purchase_orders INNER JOIN purchase_order_miscs ON purchase_orders.id = purchase_order_miscs.purchase_order_id
UNION ALL
SELECT total_price * -1 AS total_cost FROM purchase_returns INNER JOIN purchase_return_miscs ON purchase_returns.id = purchase_return_miscs.purchase_return_id
) AS CombinedData;

SELECT product_id AS itemId, product_name AS itemName, SUM(qty) AS qty, uom_name AS uomName, SUM(total_price) AS totalCost FROM ( SELECT po.id, 'Bill' AS trans_type, p.parent_id, CONCAT_WS(' ', parent_prod.code, '-', parent_prod.name) AS parent_name, pod.product_id, CONCAT_WS(' ', p.code, p.name) AS product_name, po.order_date, po.po_code AS code, v.name AS vendor_name, l.name AS location_name, (pod.qty * pod.conversion) AS qty, COALESCE( (SELECT u.name FROM uoms u JOIN uom_conversions uc ON u.id = uc.to_uom_id WHERE uc.from_uom_id = p.price_uom_id AND uc.is_small_uom = 1 AND uc.is_active = 1 LIMIT 1), (SELECT u.name FROM uoms u WHERE u.id = p.price_uom_id) ) AS uom_name, p.small_val_uom, p.price_uom_id, pod.unit_cost AS unit_price, pod.total_cost AS total_price FROM purchase_orders po INNER JOIN purchase_order_details pod ON po.id = pod.purchase_order_id INNER JOIN products p ON p.id = pod.product_id LEFT JOIN products parent_prod ON p.parent_id = parent_prod.id LEFT JOIN vendors v ON po.vendor_id = v.id LEFT JOIN locations l ON po.location_id = l.id
UNION ALL
SELECT pr.id, 'Credit' AS trans_type, p.parent_id, CONCAT_WS(' ', parent_prod.code, '-', parent_prod.name) AS parent_name, prd.product_id, CONCAT_WS(' ', p.code, p.name) AS product_name, pr.order_date, pr.pr_code AS code, v.name AS vendor_name, l.name AS location_name, (prd.qty * prd.conversion) * -1 AS qty, COALESCE( (SELECT u.name FROM uoms u JOIN uom_conversions uc ON u.id = uc.to_uom_id WHERE uc.from_uom_id = p.price_uom_id AND uc.is_small_uom = 1 AND uc.is_active = 1 LIMIT 1), (SELECT u.name FROM uoms u WHERE u.id = p.price_uom_id) ) AS uom_name, p.small_val_uom, p.price_uom_id, prd.unit_price, prd.total_price * -1 AS total_price FROM purchase_returns pr INNER JOIN purchase_return_details prd ON pr.id = prd.purchase_return_id INNER JOIN products p ON p.id = prd.product_id LEFT JOIN products parent_prod ON p.parent_id = parent_prod.id LEFT JOIN vendors v ON pr.vendor_id = v.id LEFT JOIN locations l ON pr.location_id = l.id
) AS CombinedData GROUP BY product_id, product_name, uom_name ORDER BY product_name ASC;

SELECT SUM(total_cost) AS totalCost FROM ( SELECT total_cost AS total_cost FROM purchase_orders INNER JOIN purchase_order_services ON purchase_orders.id = purchase_order_services.purchase_order_id
UNION ALL
SELECT total_price * -1 AS total_cost FROM purchase_returns INNER JOIN purchase_return_services ON purchase_returns.id = purchase_return_services.purchase_return_id
) AS CombinedData;

SELECT product_id AS itemId, product_name AS itemName, SUM(qty) AS qty, (SELECT name FROM uoms WHERE id IN (SELECT price_uom_id FROM products WHERE id = product_id)) AS uomName, SUM(total_price) AS totalCost FROM ( SELECT purchase_orders.id, 'Bill' AS trans_type, products.parent_id AS parent_id, (SELECT CONCAT_WS(' ',code,'-',name) FROM products WHERE id=products.parent_id) AS parent_name, purchase_order_details.product_id, CONCAT_WS(' ',products.code,products.name) AS product_name, purchase_orders.order_date AS order_date, purchase_orders.po_code AS code, (SELECT name FROM vendors WHERE id=purchase_orders.vendor_id) AS vendor_name, (SELECT name FROM locations WHERE id=purchase_orders.location_id) AS location_name, ((purchase_order_details.qty + purchase_order_details.qty_free) * purchase_order_details.conversion) AS qty, IFNULL((SELECT name FROM uoms WHERE id = (SELECT to_uom_id FROM uom_conversions WHERE from_uom_id = products.price_uom_id AND is_small_uom = 1 AND is_active = 1 LIMIT 1)), (SELECT name FROM uoms WHERE id = products.price_uom_id)) AS small_uom_name, purchase_order_details.unit_cost AS unit_price, purchase_order_details.total_cost AS total_price FROM purchase_orders INNER JOIN purchase_order_details ON purchase_orders.id=purchase_order_details.purchase_order_id INNER JOIN products ON products.id = purchase_order_details.product_id
UNION ALL SELECT purchase_returns.id, 'Credit' AS trans_type, products.parent_id AS parent_id, (SELECT CONCAT_WS(' ',code,'-',name) FROM products WHERE id=products.parent_id) AS parent_name, purchase_return_details.product_id, CONCAT_WS(' ',products.code,products.name) AS product_name, purchase_returns.order_date AS order_date, purchase_returns.pr_code AS code, (SELECT name FROM vendors WHERE id=purchase_returns.vendor_id) AS vendor_name, (SELECT name FROM locations WHERE id=purchase_returns.location_id) AS location_name, (purchase_return_details.qty * purchase_return_details.conversion)*-1 AS qty, IFNULL((SELECT name FROM uoms WHERE id = (SELECT to_uom_id FROM uom_conversions WHERE from_uom_id = products.price_uom_id AND is_small_uom = 1 AND is_active = 1 LIMIT 1)), (SELECT name FROM uoms WHERE id = products.price_uom_id)) AS small_uom_name, purchase_return_details.unit_price AS unit_price, purchase_return_details.total_price*-1 AS total_price FROM purchase_returns INNER JOIN purchase_return_details ON purchase_returns.id=purchase_return_details.purchase_return_id INNER JOIN products ON products.id = purchase_return_details.product_id
) AS CombinedData GROUP BY product_name ORDER BY product_name ASC

SELECT purchase_order_details.product_id AS productId, CONCAT_WS(' ',products.code,products.name) AS productName, 'Bill' AS type, purchase_orders.order_date AS `date`, purchase_orders.po_code AS code, (SELECT name FROM vendors WHERE id = purchase_orders.vendor_id) AS vendorName, (SELECT name FROM locations WHERE id = purchase_orders.location_id) AS locationName, (SELECT name FROM uoms WHERE id = purchase_order_details.qty_uom_id) AS uomName, purchase_order_details.qty AS qty, purchase_order_details.unit_cost AS unitCost, purchase_order_details.total_cost AS totalCost FROM purchase_orders INNER JOIN purchase_order_details ON purchase_orders.id=purchase_order_details.purchase_order_id INNER JOIN products ON products.id = purchase_order_details.product_id
AND purchase_order_details.product_id = #{parentId}
UNION ALL
SELECT purchase_return_details.product_id AS productId, CONCAT_WS(' ',products.code,products.name) AS productName, 'Credit' AS type, purchase_returns.order_date AS `date`, purchase_returns.pr_code AS code, (SELECT name FROM vendors WHERE id = purchase_returns.vendor_id) AS vendorName, (SELECT name FROM locations WHERE id = purchase_returns.location_id) AS locationName, (SELECT name FROM uoms WHERE id = purchase_return_details.qty_uom_id) AS uomName, purchase_return_details.qty AS qty, purchase_return_details.unit_price AS unitCost, purchase_return_details.total_price*-1 AS totalCost FROM purchase_returns INNER JOIN purchase_return_details ON purchase_returns.id=purchase_return_details.purchase_return_id INNER JOIN products ON products.id = purchase_return_details.product_id
AND purchase_return_details.product_id = #{parentId}

SELECT SUM(total_price) AS totalCost FROM ( SELECT service_id, (SELECT name FROM services WHERE id=service_id) AS service_name, qty, total_cost AS total_price FROM purchase_orders INNER JOIN purchase_order_services ON purchase_orders.id=purchase_order_services.purchase_order_id
UNION ALL
SELECT service_id, (SELECT name FROM services WHERE id=service_id) AS service_name, qty*-1 AS qty, total_price*-1 AS total_price FROM purchase_returns INNER JOIN purchase_return_services ON purchase_returns.id=purchase_return_services.purchase_return_id
) AS CombinedData;

SELECT SUM(total_cost) AS totalCost FROM ( SELECT total_cost AS total_cost FROM purchase_orders INNER JOIN purchase_order_miscs ON purchase_orders.id = purchase_order_miscs.purchase_order_id
UNION ALL
SELECT total_price * -1 AS total_cost FROM purchase_returns INNER JOIN purchase_return_miscs ON purchase_returns.id = purchase_return_miscs.purchase_return_id
) AS CombinedData;

SELECT
v.id AS vendorId,
v.name AS vendorName
FROM vendors v
WHERE v.is_active = 1
AND EXISTS (
SELECT 1 FROM general_ledgers gl
INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id
WHERE gld.vendor_id = v.id
AND gl.is_approve = 1
AND gl.is_active = 1
AND gld.chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_type_id = 6)
AND gld.type = 'Pay Bill'


        AND gld.company_id = #{filter.companyId}


        AND gld.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})



    AND gl.date >= #{filter.dateFrom}


    AND gl.date <= #{filter.dateTo}


    AND gld.vendor_id = #{filter.vendorId}


    AND gld.class_id = #{filter.classId}


    AND gl.is_adj = #{filter.isAdj}

)

    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT
type AS type,
date AS `date`,
(SELECT name FROM companies WHERE id=gld.company_id) AS companyName,
gl.reference AS reference,
(SELECT CONCAT(account_codes," · ",account_description) FROM chart_accounts WHERE id=gld.chart_account_id) AS chartAccountName,
IF(debit>0,debit,credit*-1) AS amount
FROM general_ledgers gl
INNER JOIN general_ledger_details gld ON gl.id=gld.general_ledger_id
WHERE gl.is_approve = 1
AND gld.vendor_id = #{id}
AND gld.type = 'Pay Bill'


        AND gld.company_id = #{filter.companyId}


        AND gld.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})



    AND gl.date >= #{filter.dateFrom}


    AND gl.date <= #{filter.dateTo}


    AND gld.vendor_id = #{filter.vendorId}


    AND gld.class_id = #{filter.classId}


    AND gl.is_adj = #{filter.isAdj}

AND gl.is_active = 1
AND gld.chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_type_id = 6)

SELECT COUNT(v.id)
FROM vendors v
