    AND gl.date >= #{filter.dateFrom}


    AND gl.date <= #{filter.dateTo}


    AND gld.vendor_id = #{filter.vendorId}


    AND gld.class_id = #{filter.classId}


    AND gl.is_adj = #{filter.isAdj}

)

SELECT SUM(IF(debit>0,debit,credit*-1))
FROM general_ledgers gl
INNER JOIN general_ledger_details gld ON gl.id=gld.general_ledger_id
WHERE gl.is_approve = 1
AND gld.type = 'Pay Bill'


        AND gld.company_id = #{filter.companyId}


        AND gld.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})



    AND gl.date >= #{filter.dateFrom}


    AND gl.date <= #{filter.dateTo}


    AND gld.vendor_id = #{filter.vendorId}


    AND gld.class_id = #{filter.classId}


    AND gl.is_adj = #{filter.isAdj}

AND gl.is_active = 1
AND gld.chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_type_id = 6)
